export interface IMorphOverlayState<T> {
  /** The live pose — geometry follows it directly. */
  pose: IMorphOverlayPose;
  /** What the card shows: the held value through a crossing's out beat,
   * the live one otherwise. Content-side rendering reads this. */
  shown: T;
  shownKey: string;
  /** The two-phase branch fade over the card contents: 1 whenever no
   * crossing is in flight. */
  swapFade: SharedValue<number>;
  /** Capsule↔card content window: 0 at the capsule, 1 at the card. */
  progress: SharedValue<number>;
  /** The geometry springs, published for content layers that position
   * against the container's box (a centered stage layer needs the live
   * width; the rest are the view's own). Offsets derived from these in
   * the transform lane should snap to the pixel grid at rest — Yoga
   * rounds layout, transforms apply verbatim (see DeviceStage's replica
   * centering for the pattern and the jagged glyphs it avoids). */
  width: SharedValue<number>;
  height: SharedValue<number>;
  radius: SharedValue<number>;
  lift: SharedValue<number>;
  presence: SharedValue<number>;
  /** The Dynamic Island morph's content window: 0 while the shell is
   * the bare island, 1 at rest — and 1 throughout wherever there is no
   * island. Content layers multiply their opacity by it. */
  reveal: SharedValue<number>;
  /** The capsule's measured rest size — the caller's row plus the
   * capsule's own padding (estimates until the first layout report). */
  pillSize: { width: number; height: number };
  reducedMotion: boolean;
  /** @internal wiring between the hook and the view. */
  onPillLayout: (event: LayoutChangeEvent) => void;
}

/**
 * The overlay's state: the crossing machine, the geometry springs and
 * the capsule measurement. Call it first, build the slots off `shown`
 * and the motion values, then hand everything to `<MorphOverlay/>`.
 */
export function useMorphOverlay<T>(
  live: IMorphOverlayContent<T>,
): IMorphOverlayState<T> {
  const reducedMotion = useReducedMotion();

  // The crossing machine: a change of key holds the shown value while
  // the outgoing side fades on the out beat, lands it on the empty beat
  // — content and height target together, in one piece — then reveals
  // on the in beat. Pose flips bypass the machine in BOTH directions:
  // the pose windows carry those changes, and the effect below lands
  // them silently (see the held.pose branch) — a key change only runs
  // the two-phase swap between two card arrangements.
  const [held, setHeld] = useState<IMorphOverlayContent<T>>(live);
  const crossing =
    live.pose === 'card' && held.pose === 'card' && held.key !== live.key;
  const shown = crossing ? held : live;
  const targetRef = useRef(live);
  targetRef.current = live;
  const swapFade = useSharedValue(1);
  // Only lands the value; the reveal happens in the effect below, AFTER
  // the landed content has committed (a shared-value write issued next
  // to the setState reaches the UI thread a frame early).
  const land = useCallback(() => {
    setHeld(targetRef.current);
  }, []);
  const { key: liveKey, pose: livePose, value: liveValue } = live;
  useEffect(() => {
    const heldIsLive =
      Object.is(held.value, liveValue) &&
      held.key === liveKey &&
      held.pose === livePose;
    if (livePose !== 'card') {
      // The card is not on show: land silently, the pose windows carry
      // whatever changed.
      cancelAnimation(swapFade);
      swapFade.value = 1;
      if (!heldIsLive) {
        setHeld({ value: liveValue, pose: livePose, key: liveKey });
      }
      return;
    }
    if (heldIsLive) {
      // The reveal after a landing — and the re-aim that heals an
      // interrupted out-phase, so the card can never stay half-lit. A
      // fade already resting at 1 needs neither, and skipping it spares
      // every swapFade-driven style a no-op timing's worth of frames.
      cancelAnimation(swapFade);
      if (swapFade.value === 1) {
        return;
      }
      if (reducedMotion) {
        swapFade.value = 1;
        return;
      }
      swapFade.value = withTiming(1, {
        duration: SWAP_IN_MS,
        easing: easeOutFn,
      });
      return;
    }
    if (held.key === liveKey) {
      // Same key: `shown` already follows the live value — this only
      // keeps the bookkeeping current.
      setHeld({ value: liveValue, pose: livePose, key: liveKey });
      return;
    }
    if (held.pose !== 'card') {
      // A pose flip INTO the card (capsule or hidden -> card): not a
      // crossing — `shown` already follows the live value and the pose
      // window alone carries the arrival. Land silently with the fade
      // at rest; running the two-phase swap here would multiply a dip
      // into the window's own fade-in (a visible dark-bright-dark
      // flicker) and spend a mid-flight land commit for nothing.
      cancelAnimation(swapFade);
      swapFade.value = 1;
      setHeld({ value: liveValue, pose: livePose, key: liveKey });
      return;
    }
    if (reducedMotion) {
      cancelAnimation(swapFade);
      swapFade.value = 1;
      setHeld({ value: liveValue, pose: livePose, key: liveKey });
      return;
    }
    cancelAnimation(swapFade);
    swapFade.value = withTiming(
      0,
      { duration: SWAP_OUT_MS, easing: easeInFn },
      (finished) => {
        if (finished) runOnJS(land)();
      },
    );
  }, [held, land, liveKey, livePose, liveValue, reducedMotion, swapFade]);

  // Both rest poses hug their content: the capsule row (the caller's
  // content inside the capsule's own padding, so its box IS the capsule)
  // and the active card column each report their natural size and the
  // springs re-aim to the measured rests. The estimates only cover the
  // first frames of a fresh pose.
  const [pillSize, setPillSize] = useState<{ width: number; height: number }>({
    width: PILL_REST.estimatedWidth,
    height: PILL_REST.estimatedHeight,
  });
  const onPillLayout = useCallback((event: LayoutChangeEvent) => {
    const { width: rowWidth, height: rowHeight } = event.nativeEvent.layout;
    const next = { width: Math.ceil(rowWidth), height: Math.ceil(rowHeight) };
    // Same box, same state: capsule word swaps remount the keyed row and
    // re-report, and an unchanged measurement should not re-render the
    // whole stage or re-aim settled springs.
    setPillSize((current) =>
      current.width === next.width && current.height === next.height
        ? current
        : next,
    );
  }, []);

  // One spring per geometry axis, re-aimed together on every pose or
  // measurement change — not a single progress interpolation, which would
  // snap card-to-card height changes instead of springing them (with the
  // pose held, a progress spring has nowhere left to travel). `progress`
  // survives only as the content fade window between the two poses;
  // `presence` is the whole shell's being-there, the hidden pose's axis
  // — and the dismiss drag's.
  // Rest values are estimates; the view's first layout effect lands the
  // real pose targets before anything paints.
  const width = useSharedValue(PILL_REST.estimatedWidth);
  const height = useSharedValue(PILL_REST.estimatedHeight);
  const radius = useSharedValue(PILL_REST.estimatedHeight / 2);
  const lift = useSharedValue(CARD.margin);
  const progress = useSharedValue(live.pose === 'card' ? 1 : 0);
  const presence = useSharedValue(live.pose === 'hidden' ? 0 : 1);
  const reveal = useSharedValue(1);

  return {
    pose: live.pose,
    shown: shown.value,
    shownKey: shown.key,
    swapFade,
    progress,
    width,
    height,
    radius,
    lift,
    presence,
    reveal,
    pillSize,
    reducedMotion,
    onPillLayout,
  };
}

export interface IMorphOverlayProps<T> {
  morph: IMorphOverlayState<T>;
  /** The shown card column's own height — the caller's measured blocks,
   * chrome excluded; the container adds its toolbar band and its chin. */
  cardInnerHeight: number;
  /**
   * Whether that height is real yet. A crossing lands content and height
   * target together because the incoming content was measured while
   * parked; only cold content has no numbers on its land commit, and
   * aiming there would dip the box toward a phantom target — so that one
   * defers to the first report, a frame later, still inside the empty
   * beat.
   */
  cardContentMeasured: boolean;
  /**
   * The live in-card move the height should ride `ARRANGE_MS` for
   * instead of the spring: while the card stays put and this token
   * changes between two defined values, the height runs on the
   * arrangement clock (DeviceStage passes its staged arrangement kind —
   * the confirm shrink and back). Compared, never measured.
   * Undefined-to-value edges keep the spring.
   */
  heightArrangeToken?: string | number;
  /** The caller's own flow aimed on the container's clock — see
   * IMorphAimFacts. Its identity is an effect dependency on purpose:
   * wrap it in useCallback over the flow targets, and a target change
   * re-aims. */
  onAim?: (facts: IMorphAimFacts) => void;
  /**
   * The person's way out, and the switch for every dismissal at once:
   * given, the card wears its close button and follows an upward drag
   * (release past half the card, or with momentum, dismisses), and the
   * capsule wears its trailing close button; absent, none of those
   * exist and the stage can only be left by the driver. Tapping outside
   * never dismisses — a stray tap must not cancel a device operation.
   * When to grant it is the driver's policy (the hardware flows arm it
   * on a timer). A dismissing drag has already started the exit when
   * this fires — the driver must answer by moving the content to the
   * hidden pose.
   */
  onDismiss?: () => void;
  /**
   * What the close buttons say to a screen reader — the dismissal's
   * meaning in the caller's words ("Cancel" for the hardware flows).
   */
  dismissLabel?: string;
  /**
   * Whether the app behind is blocked while the shell is there. On, an
   * invisible wall takes every touch outside the shell — the person
   * stays with the overlay until it leaves; the wall itself never
   * dismisses (the system sheet's own rule — only the drag and the
   * close button do). Off, the app behind stays live — the system
   * sheet's undimmed, non-modal mode.
   */
  modal?: boolean;
  /**
   * The dark scrim over the blocked app (implies `modal`), fading with
   * the shell's presence, and cross-fading when flipped while the shell
   * is up. The design's overlay layer — off for the hardware asks and
   * waits, which block without dimming; on for their terminal failure
   * cards (OK-62072).
   */
  scrim?: boolean;
  /**
   * Fires when the box's size comes to rest — on the height animation's
   * own completion (the size axis every transition class moves: pose
   * flights spring it, live in-card moves run it on the arrangement
   * clock), and immediately when a change lands without motion (a snap,
   * an entrance, reduced motion, the hidden pose). May fire more than
   * once per flight (effect re-runs re-aim the animation); treat it as
   * level, not edge. Content uses it to end flight-scoped economies
   * (DeviceStage holds the scene handover while the box is moving —
   * see there).
   */
  onGeometrySettled?: () => void;
  /** Keyed capsule row: a key change swaps the row in place with a fade
   * — the capsule itself never moves. */
  capsuleKey: string;
  capsule: ReactNode;
  /** The card's other corner seat: a small badge absolute at the top
   * left, the close button's mirror. Unused by the stage since
   * 2026-09-03 (it names the device on the title row now); the seat
   * stays for a badge that belongs to the window rather than the words.
   * Rides the toolbar band, so it fades with the card window. Null
   * renders nothing. */
  cornerBadge?: ReactNode;
  /** Optional layer between the face and the card seats — content that
   * must composite under the seats but over the face (DeviceStage's
   * standing replica). */
  stageLayer?: ReactNode;
  /** The parked card columns. Seats never mount or unmount with the
   * shown step — parking is the caller's warm-up policy — and exactly
   * one is active. */
  seats: Array<{ key: string; active: boolean; node: ReactNode }>;
}

export function MorphOverlay<T>({
  morph,
  cardInnerHeight,
  cardContentMeasured,
  heightArrangeToken,
  onAim,
  onDismiss,
  dismissLabel,
  onGeometrySettled,
  modal = false,
  scrim = false,
  capsuleKey,
  capsule,
  cornerBadge,
  stageLayer,
  seats,
}: IMorphOverlayProps<T>) {
  const {
    pose,
    shownKey,
    swapFade,
    progress,
    width,
    height,
    radius,
    lift,
    presence,
    reveal,
    pillSize,
    reducedMotion,
    onPillLayout,
  } = morph;
  const { width: screenWidth } = useWindowDimensions();
  const themeName = useThemeName();
  // The shell's edge definition — the native ring's hairline border, the
  // web outline — is the dark theme's neutral3 whatever the app's theme:
  // the shell is committed dark, and a light-theme edge on it read as a
  // pale halo. (borderDisabled maps to neutral3 in both themes, so the
  // native ring and the web outline are one value.)
  const shellEdgeColor = getTokenValue('$neutral3Dark', 'color');
  const media = useMedia();
  // The window class, on the Dialog's own sheet↔panel line (md, a
  // phone-class window). The shell hangs from the top on both sides of
  // it; the class only picks the capsule's seat and caps the card's
  // width on the wide side (iPad, desktop, a wide web tab).
  const phoneClass = media.md;
  const isSpanning = useIsSpanningInDualScreen();
  const isAndroidFoldable = platformEnv.isNativeAndroid && isDualScreenDevice();
  // An expanded Android foldable stays a phone-class window (the native
  // media driver clamps it), so the cap is its own call: a card spanning
  // both halves must not stretch edge to edge (OK-63187).
  const capCardWidth = !phoneClass || (isAndroidFoldable && isSpanning);
  // The shell's seat on a phone-class window: under the status bar band
  // — the notification banner's place — with the card's own margin of
  // air, capsule and card alike. The band is the top inset: on an island
  // or notch phone it carries the cutout, which nothing can paint over,
  // and the clock, which the system paints over everything; a wide
  // window has no band to speak of and keeps its own constants.
  const insets = useSafeAreaInsets();
  const phoneTop = insets.top + CARD.margin;
  const pillTop = phoneClass ? phoneTop : PILL.wideTop;
  const cardTop = phoneClass ? phoneTop : CARD.margin;
  // The Dynamic Island, when the window has one: the rectangle every
  // entrance grows out of and every programmatic exit shrinks back into
  // (see ./dynamicIsland). Read off the same inset, so a rotation
  // (landscape reports no inset) drops it and the plain slide takes over.
  const island = useMemo(
    () => dynamicIslandRect(insets.top, platformEnv.isNativeIOSPhone),
    [insets.top],
  );
  const cardWidth = capCardWidth
    ? Math.min(screenWidth - CARD.margin * 2, CARD.maxWidth)
    : screenWidth - CARD.margin * 2;
  const cardHeight = CARD.padTop + cardInnerHeight + CARD.bottomPad;
  const dismissible = Boolean(onDismiss);
  const dragEnabled = dismissible && pose === 'card';
  // Each enabled period owns its grant. Reopening must never re-arm the
  // shared value retained by a recognizer from before the stage hid.
  const dragAllowed = useMemo(() => makeMutable(dragEnabled), [dragEnabled]);
  useLayoutEffect(() => {
    dragAllowed.value = dragEnabled;
    return () => {
      dragAllowed.value = false;
    };
  }, [dragAllowed, dragEnabled]);
  const blocking = modal || scrim;
  // The capsule's close button rides outside the measured row, so the
  // box simply widens by the button when the grant arrives — no
  // re-measure, and the row's words never rebuild for it.
  const pillWidth = pillSize.width + (dismissible ? CLOSE.size : 0);
  const cardRadius = CARD.radius;

  // The lit seat, as a shared value — see PanelSeat for why.
  const activeSeatKey = seats.find((seat) => seat.active)?.key;
  const litKey = useSharedValue<string | undefined>(activeSeatKey);

  const prevPoseRef = useRef(pose);
  const prevKeyRef = useRef(shownKey);
  const prevTokenRef = useRef(heightArrangeToken);
  const firstRunRef = useRef(true);
  // Layout effect on purpose: the springs are aimed before this commit
  // paints, so the first morph frame ships with the driver's own
  // re-render instead of one frame behind it — and the mount lands its
  // pose targets before the estimates ever paint.
  useLayoutEffect(() => {
    // First, before anything can reveal: the seat flip rides the same
    // turn as every aim below, and as the reveal the hook issues after.
    litKey.value = activeSeatKey;
    const prevPose = prevPoseRef.current;
    prevPoseRef.current = pose;
    const prevKey = prevKeyRef.current;
    prevKeyRef.current = shownKey;
    const prevToken = prevTokenRef.current;
    prevTokenRef.current = heightArrangeToken;
    const first = firstRunRef.current;
    firstRunRef.current = false;
    // The island the shell morphs out of and back into — none on the
    // mount's own landing, under reduced motion, or without an island.
    const growFrom = first || reducedMotion ? undefined : island;
    // The settled signal rides the height animation, not the progress
    // spring: height is the one size axis every transition class moves
    // (a live in-card move never touches progress), so "settled" means
    // the size has actually landed, crossings and flights alike. A
    // re-aim mid-flight reports unfinished and stays silent. Explicit
    // 'worklet' directive: the babel plugin only converts callbacks
    // written inline in the animation call on its own.
    const notifySettled = (finished?: boolean) => {
      'worklet';

      if (finished && onGeometrySettled) {
        runOnJS(onGeometrySettled)();
      }
    };
    if (pose === 'hidden') {
      // A programmatic exit on an island phone shrinks the shell back
      // into the island, the content hiding ahead of the box; the
      // presence gate closes the moment the box lands on the island's
      // own rectangle — where the shell IS the island, so the gate is
      // invisible. Every other exit slides whole past the top edge,
      // opaque all the way — the notification's move — and geometry
      // holds, so the slide never doubles as a shrink. After a
      // dismissing drag the slide is already in flight on the presence
      // axis (the finger's own line): the spring re-aimed here simply
      // carries on, velocity and all, and never turns into a shrink.
      if (growFrom && presence.value === 1) {
        reveal.value = withTiming(0, {
          duration: ISLAND_HIDE_MS,
          easing: easeInFn,
        });
        width.value = withSpring(growFrom.width, MORPH_SPRING);
        height.value = withSpring(
          growFrom.height,
          MORPH_SPRING,
          (finished?: boolean) => {
            'worklet';

            if (finished) {
              presence.value = 0;
            }
          },
        );
        radius.value = withSpring(growFrom.radius, MORPH_SPRING);
        lift.value = withSpring(growFrom.top, MORPH_SPRING);
      } else {
        presence.value =
          first || reducedMotion ? 0 : withSpring(0, MORPH_SPRING);
      }
      onGeometrySettled?.();
      return;
    }
    const card = pose === 'card';
    const targets = {
      width: card ? cardWidth : pillWidth,
      height: card ? cardHeight : pillSize.height,
      // A capsule's radius tracks its own height — always half of it.
      radius: card ? cardRadius : pillSize.height / 2,
      lift: card ? cardTop : pillTop,
      progress: card ? 1 : 0,
    };
    // An entrance appears already at its pose: on an island phone the
    // shell appears AS the island (its own rectangle, presence already
    // up — indistinguishable from the island itself) and grows to the
    // pose from there, the content revealing a beat behind the box;
    // elsewhere geometry snaps while the shell is still invisible and
    // presence carries the arrival, the slide in from the top edge. The
    // very first run is the mount landing on whatever pose it opened at.
    // The snap window outlives the arrival commit (the presence check):
    // while presence is under overshoot/(height+lift+overshoot) — the
    // same travel math as positionStyle — the door has not yet lowered
    // the shell's bottom past the top edge, so a measure landing a
    // frame later (parked content flipped on the entrance itself, see
    // DeviceStage's stage tail) corrects the geometry in place while
    // provably off screen, instead of visibly springing under the
    // reveal. (The island entrance runs presence at 1 from its first
    // frame, so a later measure re-aims springs already in flight — the
    // box is growing anyway.)
    const offscreenAbove =
      EXIT_OVERSHOOT / (targets.height + targets.lift + EXIT_OVERSHOOT);
    const arriving = prevPose === 'hidden' || presence.value < offscreenAbove;
    if (first || reducedMotion || arriving) {
      if (growFrom) {
        width.value = growFrom.width;
        height.value = growFrom.height;
        radius.value = growFrom.radius;
        lift.value = growFrom.top;
        reveal.value = 0;
        progress.value = targets.progress;
        onAim?.({ snap: true, card, landInPlace: true });
        presence.value = 1;
        width.value = withSpring(targets.width, MORPH_SPRING);
        height.value = withSpring(targets.height, MORPH_SPRING, notifySettled);
        radius.value = withSpring(targets.radius, MORPH_SPRING);
        lift.value = withSpring(targets.lift, MORPH_SPRING);
        reveal.value = withDelay(
          ISLAND_REVEAL_DELAY_MS,
          withTiming(1, { duration: ISLAND_REVEAL_MS, easing: easeOutFn }),
        );
        return;
      }
      width.value = targets.width;
      height.value = targets.height;
      radius.value = targets.radius;
      lift.value = targets.lift;
      reveal.value = 1;
      progress.value = targets.progress;
      onAim?.({ snap: true, card, landInPlace: true });
      presence.value = first || reducedMotion ? 1 : withSpring(1, MORPH_SPRING);
      onGeometrySettled?.();
      return;
    }
    // Content flow first (same frame either way), then the box springs.
    // The caller's targets only ever change with the shown value — a
    // crossing re-aims them exactly once, on the empty beat.
    const landInPlace = prevPose !== 'card' || prevKey !== shownKey;
    onAim?.({ snap: false, card, landInPlace });
    // A live in-card move (the token changing between two defined
    // values while the card stays put) runs the height on the
    // arrangement clock; everything else rides the box springs.
    const heightRidesArrange =
      card &&
      prevPose === 'card' &&
      prevToken !== undefined &&
      heightArrangeToken !== undefined &&
      prevToken !== heightArrangeToken;
    presence.value = withSpring(1, MORPH_SPRING);
    width.value = withSpring(targets.width, MORPH_SPRING);
    // A crossing lands content and height target together — in one
    // piece — see `cardContentMeasured` for the one deferral.
    const landed = card && prevPose === 'card' && prevKey !== shownKey;
    if (!landed || cardContentMeasured) {
      height.value = heightRidesArrange
        ? withTiming(
            targets.height,
            { duration: ARRANGE_MS, easing: arrangeEase },
            notifySettled,
          )
        : withSpring(targets.height, MORPH_SPRING, notifySettled);
    }
    radius.value = withSpring(targets.radius, MORPH_SPRING);
    lift.value = withSpring(targets.lift, MORPH_SPRING);
    progress.value = withSpring(targets.progress, MORPH_SPRING);
  }, [
    onGeometrySettled,
    activeSeatKey,
    cardContentMeasured,
    cardHeight,
    cardRadius,
    cardTop,
    cardWidth,
    height,
    heightArrangeToken,
    island,
    lift,
    litKey,
    onAim,
    pillSize,
    pillTop,
    pillWidth,
    pose,
    presence,
    progress,
    radius,
    reducedMotion,
    reveal,
    shownKey,
    width,
  ]);

  // The pose's resting bottom edge, for the toasters (see Toast's
  // topObstruction): they land where the shell hangs, so they clear it
  // instead of covering it. The exit publishes 0 as it starts, and the
  // toasts rise behind the departing shell. A card still waiting on its
  // content measure holds the last edge — its height lands a commit
  // later, and the toasts would re-aim mid-ride.
  let restingBottom = 0;
  if (pose === 'card') {
    restingBottom = cardTop + cardHeight;
  } else if (pose === 'capsule') {
    restingBottom = pillTop + pillSize.height;
  }
  const restingBottomSettled = pose !== 'card' || cardContentMeasured;
  useEffect(() => {
    if (restingBottomSettled) {
      publishToastTopObstruction(restingBottom);
    }
  }, [restingBottom, restingBottomSettled]);
  useEffect(() => () => publishToastTopObstruction(0), []);

  // The dismiss callback rides a ref so the gesture never rebuilds for a
  // fresh closure — the driver's identity is its own business.
  const onDismissRef = useRef(onDismiss);
  onDismissRef.current = onDismiss;
  const dismiss = useCallback(() => {
    onDismissRef.current?.();
  }, []);
  const dismissFromDrag = useCallback(() => {
    // The stage may have hidden and reopened while runOnJS was queued.
    if (dragAllowed.value) dismiss();
  }, [dismiss, dragAllowed]);
  // The drag rides presence — see DRAG_*. Armed only for a dismissible
  // card: the capsule has no drag (its close button is its one exit),
  // and an unarmed stage cannot be pulled at all.
  const pan = useMemo(
    () =>
      Gesture.Pan()
        .enabled(dragEnabled)
        .activeOffsetY([-DRAG_ACTIVATION_PT, DRAG_ACTIVATION_PT])
        .onUpdate((event) => {
          if (!dragAllowed.value) return;
          // The dismissing direction is the anchored edge's own: up, off
          // the top. Normalized here, the rest of the math only knows
          // "toward the exit".
          const drag = -event.translationY;
          // The same door the position worklet opens (see positionStyle).
          const travel = height.value + lift.value + EXIT_OVERSHOOT;
          const pull = drag >= 0 ? drag : -rubberBand(-drag, height.value);
          presence.value = 1 - pull / travel;
        })
        .onEnd((event) => {
          if (!dragAllowed.value) return;
          const drag = -event.translationY;
          const dragVelocity = -event.velocityY;
          const travel = height.value + lift.value + EXIT_OVERSHOOT;
          // Finger velocity, in presence units per second.
          const velocity = -dragVelocity / travel;
          const projected = drag + dragVelocity * DRAG_PROJECTION_S;
          if (projected > height.value * DRAG_DISMISS_FRACTION) {
            presence.value = withSpring(0, { ...MORPH_SPRING, velocity });
            runOnJS(dismissFromDrag)();
            return;
          }
          presence.value = withSpring(1, { ...MORPH_SPRING, velocity });
        })
        .onFinalize((_event, success) => {
          // A drag taken over by another recognizer ends nowhere: rest.
          if (!success && dragAllowed.value) {
            presence.value = withSpring(1, MORPH_SPRING);
          }
        }),
    [dismissFromDrag, dragAllowed, dragEnabled, height, lift, presence],
  );

  // Size and position ride separate styles on purpose: the size worklet
  // returns layout props only (no transform array), so its output passes
  // reanimated's shallow-equal check and re-commits layout ONLY when the
  // morph moves those axes — while presence frames stay pure view
  // transforms, no Yoga pass. The layer top-anchors this single child,
  // so the lift and the translate are the same pixel.
  const geometrySizeStyle = useAnimatedStyle(
    () => ({
      width: width.value,
      height: height.value,
      borderRadius: radius.value,
    }),
    [height, radius, width],
  );
  // The one keyboard term, and a native one (the web feed reads 0): the
  // shell hangs above the app's inputs and never rides the keyboard, but
  // a card carries inputs of its own (the passphrase form, the pairing
  // code), and on a short window the system keyboard would cover the
  // actions under them. A shell whose bottom edge the keyboard covers
  // rises by exactly that overlap — its top may slip under the status bar
  // band, its actions stay reachable — and every other shell is untouched:
  // a capsule, or a card on a tall window, never reaches the keyboard.
  // The layer's own height is the window's, whatever the platform's
  // window metrics call one.
  const { height: keyboardHeight } = useReanimatedKeyboardAnimation();
  const layerHeight = useSharedValue(0);
  const handleLayerLayout = useCallback(
    (event: LayoutChangeEvent) => {
      layerHeight.value = event.nativeEvent.layout.height;
    },
    [layerHeight],
  );
  const bottomInset = insets.bottom;
  const positionStyle = useAnimatedStyle(() => {
    // Being-there, the shell's door, spoken off the top edge it hangs
    // from: a slide exit lifts the shell whole past that edge — the
    // notification's move — and a drag pulls presence under 1 (and a
    // breath over it, rubber-banded), so the finger rides this same
    // line. The island morph never moves this axis: it keeps presence
    // at 1 and shrinks the box instead.
    const travel =
      (1 - presence.value) * (height.value + lift.value + EXIT_OVERSHOOT);
    const keyboard = Math.abs(keyboardHeight.value);
    const rise =
      keyboard > 0 && layerHeight.value > 0
        ? Math.max(
            0,
            lift.value +
              height.value +
              CARD.margin -
              usableWindowBottom(
                layerHeight.value,
                bottomInset,
                keyboard,
                IS_NATIVE_ANDROID,
              ),
          )
        : 0;
    return {
      // The hard gate on the hidden rest (OK-62485): fully departed, the
      // shell paints nothing at all. The slide itself stays opaque to the
      // last frame, so no exit looks different — but the parked shell can
      // no longer be caught on screen when a layout and this transform
      // land in different frames (a rotation re-seats the capsule).
      opacity: presence.value > 0 ? 1 : 0,
      transform: [{ translateY: lift.value - travel - rise }],
    };
  }, [bottomInset, height, keyboardHeight, layerHeight, lift, presence]);
  // The scrim's being-there is the shell's: it fades with the entrance,
  // the exit and the drag alike. Its level rides a clock of its own, so a
  // flip while the shell is up (a wait turning into a failure card,
  // OK-62072) fades the tint in on the swap-in beat instead of popping;
  // at level 0 the tinted wall IS the bare transparent wall, so one style
  // serves both grants.
  const scrimLevel = useSharedValue(scrim ? 1 : 0);
  useEffect(() => {
    const target = scrim ? 1 : 0;
    scrimLevel.value = reducedMotion
      ? target
      : withTiming(target, { duration: SWAP_IN_MS });
  }, [reducedMotion, scrim, scrimLevel]);
  const scrimFadeStyle = useAnimatedStyle(
    () => ({
      opacity:
        interpolate(presence.value, [0, 1], [0, 1], Extrapolation.CLAMP) *
        reveal.value *
        scrimLevel.value,
    }),
    [presence, reveal, scrimLevel],
  );
  // The face clips, so it re-rounds in step with the shell — and the
  // native ring wears the same style to hug the same corner.
  const faceRadiusStyle = useAnimatedStyle(
    () => ({ borderRadius: radius.value }),
    [radius],
  );
  // Every content window also wears the island morph's reveal — 1
  // wherever there is no island, so nothing changes elsewhere.
  const pillFadeStyle = useAnimatedStyle(
    () => ({
      opacity:
        interpolate(
          progress.value,
          [0, PILL_OUT_END],
          [1, 0],
          Extrapolation.CLAMP,
        ) * reveal.value,
    }),
    [progress, reveal],
  );
  // The pose window times the crossing swap: swapFade is the two-phase
  // branch fade, 1 whenever no crossing is in flight. Opacity and scale
  // only — the static centering block lives in the memoized plain style
  // below, out of the per-frame worklet.
  const cardFadeStyle = useAnimatedStyle(
    () => ({
      opacity:
        swapFade.value *
        reveal.value *
        interpolate(
          progress.value,
          [CARD_IN_START, 1],
          [0, 1],
          Extrapolation.CLAMP,
        ),
      transform: [
        {
          scale: interpolate(
            progress.value,
            [CARD_IN_START, 1],
            [CARD_IN_SCALE_FROM, 1],
            Extrapolation.CLAMP,
          ),
        },
      ],
    }),
    [progress, reveal, swapFade],
  );
  // The toolbar belongs to the card pose, not to its content: it rides
  // the pose window alone, so a crossing swapping the seats underneath
  // never blinks the close button.
  const toolbarFadeStyle = useAnimatedStyle(
    () => ({
      opacity:
        interpolate(
          progress.value,
          [CARD_IN_START, 1],
          [0, 1],
          Extrapolation.CLAMP,
        ) * reveal.value,
    }),
    [progress, reveal],
  );

  // The scrim's tint over the blocked app, under its animated level —
  // fully clear without the grant. Paint only: the touch-blocking wall
  // is a static view of its own (see the render).
  const scrimStyle = useMemo(
    () => [
      styles.backdrop,
      {
        backgroundColor: `rgba(0,0,0,${
          themeName === 'dark' ? SCRIM_ALPHA.dark : SCRIM_ALPHA.light
        })`,
      },
      scrimFadeStyle,
    ],
    [scrimFadeStyle, themeName],
  );
  // The shell's edge furniture fades with the island morph's reveal: a
  // shadow halo or a hairline ring around the bare island would give
  // the morph away. Web has no island and no ring; its outline and CSS
  // shadow stay static.
  const shellRevealStyle = useAnimatedStyle(
    () => ({ shadowOpacity: SHELL_SHADOW_OPACITY * reveal.value }),
    [reveal],
  );
  const ringRevealStyle = useAnimatedStyle(
    () => ({ opacity: reveal.value }),
    [reveal],
  );
  const shellStyle = useMemo(
    () =>
      platformEnv.isNative
        ? [styles.shell, geometrySizeStyle, positionStyle, shellRevealStyle]
        : [
            styles.shell,
            geometrySizeStyle,
            positionStyle,
            { outlineColor: shellEdgeColor },
          ],
    [geometrySizeStyle, positionStyle, shellEdgeColor, shellRevealStyle],
  );
  const ringStyle = useMemo(
    () => [
      styles.ring,
      faceRadiusStyle,
      ringRevealStyle,
      { borderColor: shellEdgeColor },
    ],
    [faceRadiusStyle, ringRevealStyle, shellEdgeColor],
  );
  const faceStyle = useMemo(
    () => [styles.face, faceRadiusStyle],
    [faceRadiusStyle],
  );
  const pillStyle = useMemo(
    () => [styles.pillContent, pillFadeStyle],
    [pillFadeStyle],
  );
  const cardCenter = useMemo(
    () => ({ width: cardWidth, marginLeft: -cardWidth / 2 }),
    [cardWidth],
  );
  const cardStyle = useMemo(
    () => [styles.cardContent, cardCenter, cardFadeStyle],
    [cardCenter, cardFadeStyle],
  );
  const toolbarStyle = useMemo(
    () => [styles.toolbar, cardCenter, toolbarFadeStyle],
    [cardCenter, toolbarFadeStyle],
  );

  return (
    // The app's hardware-overlay window — the same full-window level the
    // hardware dialogs this stage replaces render into (see kit's
    // FullWindowOverlayContainer; the storybook shells mount the
    // container canvas-wide). It must sit above iOS presentations: the
    // flows that raise the stage start on modal pages (send, receive,
    // onboarding), and at any lower level those covered it. The cost is
    // the mirror case — a presentation opened UNDER a live stage (a
    // Support button's in-app browser) cannot rise above it — so a
    // driver navigating away must drop the stage first, the discipline
    // the dialogs themselves follow.
    <Portal.Body container={Portal.Constant.HARDWARE_UI_STATE_DIALOG}>
      {/* collapsable={false}: RN 0.86 Fabric flattens this layout-only
          box-none layer out of the native hierarchy, and the flattened
          path loses hit-testing for the whole subtree — the stage draws
          but nothing inside takes a touch. Keep the native view. */}
      <Stack
        style={styles.layer}
        pointerEvents="box-none"
        collapsable={false}
        onLayout={handleLayerLayout}
      >
        {/* The wall blocks the app whenever the shell is there, and is
            deliberately NOT a dismissal surface: a stray tap outside
            must never cancel a device operation mid-flight — the close
            button and the drag are the intentional exits. It unmounts at
            the hidden pose instead of flipping pointerEvents — the
            reanimated web view keeps overwriting that style, which left
            an invisible full-window wall standing after the exit and
            swallowing every touch. */}
        {/* A plain static View, split from the scrim's tint (OK-63431):
            RN's iOS hit test skips any view whose alpha is under 0.01,
            so a wall carrying the scrim's animated opacity took no
            touches in every undimmed state — the waits and the asks —
            and taps fell through to the page behind. Android's touch
            targeting and the web ignore alpha, which is why only iOS
            leaked. collapsable={false}: Fabric flattens an unpainted
            auto-pointer-events view out of the native tree, and a
            flattened wall takes nothing either. */}
        {blocking && pose !== 'hidden' ? (
          <>
            <View
              style={styles.backdrop}
              pointerEvents="auto"
              collapsable={false}
              testID="morph-overlay-wall"
            />
            {/* The tint over the blocked app — paint only, the wall
                under it does the blocking. */}
            <Animated.View style={scrimStyle} pointerEvents="none" />
          </>
        ) : null}
        <GestureDetector gesture={pan}>
          <Animated.View style={shellStyle}>
            <Animated.View style={faceStyle}>
              <Theme name="dark">
                {stageLayer}
                {/* Always mounted: this wrapper carries the pose window
                    and the crossing swapFade — the branch fade — over the
                    parked seats inside. A crossing only flips which seat
                    is lit, on the empty beat, and builds nothing. No
                    mount fades anywhere here — the wrapper owns every
                    fade, and seats never leave. */}
                <Animated.View style={cardStyle}>
                  {seats.map((seat) => (
                    <PanelSeat
                      key={seat.key}
                      seatKey={seat.key}
                      litKey={litKey}
                      active={seat.active}
                    >
                      {seat.node}
                    </PanelSeat>
                  ))}
                </Animated.View>
                {/* The card's toolbar band: the close button with the
                    grant. Over the seats, so the button stays tappable
                    above whatever column is lit. */}
                <Animated.View
                  style={toolbarStyle}
                  pointerEvents={pose === 'card' ? 'box-none' : 'none'}
                >
                  {cornerBadge ? (
                    <Animated.View
                      style={styles.cardBadge}
                      entering={FadeIn.duration(CAPSULE_SWAP_IN_MS)}
                    >
                      {cornerBadge}
                    </Animated.View>
                  ) : null}
                  {dismissible ? (
                    <Animated.View
                      style={styles.cardClose}
                      entering={FadeIn.duration(CAPSULE_SWAP_IN_MS)}
                    >
                      <CloseButton
                        testID="morph-overlay-close"
                        label={dismissLabel}
                        onPress={dismiss}
                      />
                    </Animated.View>
                  ) : null}
                </Animated.View>
                <Animated.View
                  style={pillStyle}
                  pointerEvents={pose === 'capsule' ? 'box-none' : 'none'}
                >
                  {/* Keyed by its words: a key change swaps the row in
                      place with a fade — the capsule itself never moves.
                      The padded wrapper measures the row for the
                      capsule's own rest size. */}
                  <Animated.View
                    key={capsuleKey}
                    entering={FadeIn.duration(CAPSULE_SWAP_IN_MS).delay(
                      CAPSULE_SWAP_IN_DELAY_MS,
                    )}
                    exiting={FadeOut.duration(CAPSULE_SWAP_OUT_MS)}
                  >
                    <View style={styles.pillRow} onLayout={onPillLayout}>
                      {capsule}
                    </View>
                  </Animated.View>
                  {dismissible ? (
                    <Animated.View
                      style={styles.pillClose}
                      entering={FadeIn.duration(CAPSULE_SWAP_IN_MS)}
                    >
                      <CloseButton
                        testID="morph-overlay-capsule-close"
                        label={dismissLabel}
                        onPress={dismiss}
                      />
                    </Animated.View>
                  ) : null}
                </Animated.View>
              </Theme>
            </Animated.View>
            {platformEnv.isNative ? (
              <Animated.View pointerEvents="none" style={ringStyle} />
            ) : null}
          </Animated.View>
        </GestureDetector>
      </Stack>
    </Portal.Body>
  );
}
